{
  "schema_version": "long-horizon.goal.v1",
  "goal_id": "G1",
  "objective": "Apply request.json to config.json under policy.json, producing result.json with updated_config, applied keys sorted, and rejected keys sorted, while preserving untouched config values and rejecting all keys not in allowed.",
